#pragma once

#include "raylib.h"
#include "TrackData.h" // generated by Tools/generate_track.py

enum SurfaceType
{
	SURF_ASPHALT,
	SURF_GRASS,
	SURF_SAND,
	SURF_ICE,
	SURF_COUNT
};

// What the floor is made of. The tyres grip (static friction) until the force is too big, then they slide
// (dynamic friction). The rolling resistance slows the car down when it is not sliding.
struct Surface
{
	const char* name;
	float static_friction; // mu_s
	float dynamic_friction; // mu_k
	float rolling; // rolling resistance coefficient
};

// The circuit: centerline, directions and floor types. The numbers come from TrackData.h
class Track
{
public:
	Track();

	int GetPointCount() const;
	Vector2 GetPoint(int index) const; // the index wraps around the loop
	Vector2 GetTangent(int index) const; // unit vector, direction of the race
	Vector2 GetNormalLeft(int index) const; // unit vector, left of the direction of the race

	// Closest point of the centerline. With a hint only the points around it are tested (fast and keeps
	// the continuity of the progress); without a hint (-1) all of them are tested
	int FindNearest(float x, float y, int hint = -1) const;

	// Floor under a point. nearest = result of FindNearest for the same point
	SurfaceType GetSurfaceType(float x, float y, int nearest) const;

	Surface& GetSurface(SurfaceType type);
	const Surface& GetSurface(SurfaceType type) const;

private:
	float DistanceToCenter(float x, float y, int nearest) const;

private:
	Vector2 points[TRACK_POINTS];
	Vector2 tangents[TRACK_POINTS];
	Vector2 normals[TRACK_POINTS];
	Surface surfaces[SURF_COUNT];
};
